// 1. Place 7-Minute Temporary Seat Hold
POST /api/v1/shows/shw_9912/holds
Headers:
  Idempotency-Key: hold_usr441_shw9912
  X-Waiting-Room-Token: eyJhbGciOiJFZERTQSJ9...
Request:
{
  "user_id": "usr_441",
  "seat_ids": ["A-12", "A-13"]
}
Response (201 Created — or 409 Conflict if already held):
{
  "booking_id": "bkg_77812",
  "status": "HELD",
  "seat_ids": ["A-12", "A-13"],
  "hold_expires_at": "2026-09-30T16:37:00Z",
  "checkout_Remaining_seconds": 420
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY events_shows (PostgreSQL + Read Replicas) {
  [PK ] show_id                UUID
  [IDX] venue_id               UUID
        title                  VARCHAR(255)
        start_time             TIMESTAMPTZ
        total_seats            INT
}

ENTITY show_seats (PostgreSQL (ACID + Optimistic Lock)) {
  [PK ] show_id                UUID (Composite PK)
  [PK ] seat_id                VARCHAR(16) (Composite PK)
        status                 ENUM('AVAILABLE','HELD','BOOKED')
  [IDX] hold_expires_at        TIMESTAMPTZ
        version                INT (OCC Lock)
}

ENTITY bookings (PostgreSQL (Transactional)) {
  [PK ] booking_id             UUID
  [FK ] show_id                UUID
  [IDX] user_id                UUID
        seat_ids               ARRAY<VARCHAR>
        payment_status         ENUM('PENDING','PAID')
}

// Relationships: events_shows --(1 : N (contains seats))--> show_seats --(1 : N (reserves & books))--> bookings

/*
================================================================================
FLOW 1: TWO-PHASE ATOMIC MULTI-SEAT HOLD (REDIS GATE + DB OCC WITH LAZY EXPIRY)
================================================================================
1. Sort requested seatIds ascending: [102, 101] -> [101, 102] (Prevents Deadlock)
2. Redis Lua Gatekeeper: All-or-nothing SETNX on hold:{showId}:{seatId} (EX 600s)
   -> 999 of 1,000 concurrent callers fast-fail here in 0.4ms!
3. PostgreSQL Authoritative OCC Update:
   UPDATE show_seats
   SET status = 'HELD', held_by_user = :userId, booking_id = :bookingId,
       hold_expires_at = NOW() + INTERVAL '10 minutes', version = version + 1
   WHERE show_id = :showId AND seat_id IN (101, 102)
     AND (status = 'AVAILABLE' OR (status = 'HELD' AND hold_expires_at < NOW()));
   -> Assert updatedRows == seatIds.size() (else ROLLBACK & release Redis keys)

================================================================================
FLOW 2: CONTIGUOUS SEAT ALLOCATION VIA BITMASK ("BEST AVAILABLE" MODE)
================================================================================
Row A (16 seats): 1 = Available, 0 = Taken/Held
Bitmask: 0b00111100_11001110  -> Looking for k=4 contiguous seats -> Match at bits 10..13!
*/

package com.sdi.ticketbooking.service;

import com.sdi.ticketbooking.domain.*;
import java.time.Duration;
import java.time.Instant;
import java.util.*;

public class SeatReservationEngine {

    private static final Duration HOLD_TTL = Duration.ofMinutes(10);

    private final RedisSeatLockClient redisLockClient;
    private final SeatDatabaseRepository seatRepo;

    public SeatReservationEngine(RedisSeatLockClient redisLockClient, SeatDatabaseRepository seatRepo) {
        this.redisLockClient = redisLockClient;
        this.seatRepo = seatRepo;
    }

    /**
     * FLOW 1: Two-Phase Atomic Seat Hold with Deadlock Avoidance & Lazy Expiration
     */
    public HoldSeatsResponse holdSeatsAtomically(long userId, long showId, List<Long> rawSeatIds) {
        if (rawSeatIds == null || rawSeatIds.isEmpty() || rawSeatIds.size() > 6) {
            throw new IllegalArgumentException("Must select between 1 and 6 seats");
        }

        // 1. Sort seat IDs ascending to guarantee deadlock-free lock acquisition order
        List<Long> sortedSeatIds = rawSeatIds.stream().distinct().sorted().toList();
        UUID bookingId = UUID.randomUUID();
        Instant expiresAt = Instant.now().plus(HOLD_TTL);

        // 2. Fast-Fail Redis Lua Gatekeeper (Atomic All-or-Nothing SETNX with 600s TTL)
        boolean redisLocked = redisLockClient.tryAcquireMultiSeatHold(
            showId, sortedSeatIds, bookingId.toString(), (int) HOLD_TTL.toSeconds()
        );
        if (!redisLocked) {
            throw new SeatUnavailableException("One or more selected seats are currently held");
        }

        try {
            // 3. Authoritative ACID Database Transaction with Lazy Expiration Check
            return seatRepo.executeInTransaction(tx -> {
                Instant now = Instant.now();
                int updatedCount = tx.claimAvailableOrExpiredSeats(
                    showId, sortedSeatIds, userId, bookingId, now, expiresAt
                );

                // All-or-nothing check: if any seat was already BOOKED or actively HELD, abort!
                if (updatedCount != sortedSeatIds.size()) {
                    throw new SeatUnavailableException("Seat state changed concurrently; aborting hold");
                }

                long totalCents = tx.calculateTotalPriceCents(showId, sortedSeatIds);
                tx.insertPendingBooking(bookingId, userId, showId, totalCents, expiresAt);

                return new HoldSeatsResponse(
                    bookingId, showId, sortedSeatIds, totalCents, expiresAt, "pay_tok_" + bookingId
                );
            });
        } catch (Exception ex) {
            // Compensating action: immediately free the Redis hold keys so others can book
            redisLockClient.releaseMultiSeatHold(showId, sortedSeatIds, bookingId.toString());
            throw ex;
        }
    }

    /**
     * FLOW 2: O(1) Bitwise Finder for K Contiguous Available Seats in a Row
     * @param availabilityBitmask 64-bit mask where 1 = AVAILABLE, 0 = HELD/BOOKED
     * @param k number of adjacent seats requested (e.g., 4)
     * @return starting seat index (0-based), or -1 if no k contiguous seats exist in this row
     */
    public int findContiguousSeatsBitwise(long availabilityBitmask, int k) {
        long mask = availabilityBitmask;
        for (int shift = 1; shift < k; shift++) {
            mask &= (availabilityBitmask >>> shift);
        }
        if (mask == 0L) {
            return -1; // No k adjacent available seats in this row
        }
        // Return the lowest-numbered contiguous block using trailing zeros
        return Long.numberOfTrailingZeros(mask);
    }
}
